#[test]fn invisible_living_and_marker_selection(){use true_sight::*;let m=TrueSight::default();assert_eq!(m.markers(true),3);assert_eq!(m.colors(true,true,true,false),Some([0x64ffffff,0x78ffffff]));assert_eq!(m.colors(true,false,true,false),None);assert_eq!(m.colors(false,true,true,true),Some([0x78ffffff;2]));assert_eq!(abgr(0x12345678),0x12785634);assert!(sight_tag("lIgHtS","Lights"));}
